import React, { useEffect, useState } from "react";
import './CarFilter.css';

export default function CarFilter() {

    const [brandFilter, setBrandFilter] = useState(null)
    const [modelFilter, setModelFilter] = useState(null)
    const [typeFilter, setTypeFilter] = useState(null)


    const [cars, setCars] = useState([])

    useEffect(() => {
        const fetchCars = async () => {

            let url = "http://localhost:5000/cars?";

            if (brandFilter) {
                url += `brand=${brandFilter}&`;
            }

            if (modelFilter) {
                url += `model=${modelFilter}&`;
            }

            if (typeFilter) {
                url += `type=${typeFilter}&`;
            }

            const response = await fetch(url);

            const data = await response.json();

            setCars(data);
        }

        fetchCars();
    },[brandFilter, modelFilter, typeFilter])

    const brands = [...new Set(cars.map((car) => car.brand))];

    const models = [...new Set(cars.map((car) => car.model))];

    const types = [...new Set(cars.map((car) => car.type))];

    useEffect(() => {
        console.log(models)
    },[models])

    useEffect(() => {
        console.log(brandFilter)
    },[brandFilter])

    return (
        <div className="root">
            <div className="filter">
                <div className="brand">
                    <h3>--- Marque ---</h3>
                    <div className="input">
                        <input type="checkbox" checked={brandFilter === 'BMW'} onChange={() => setBrandFilter(brandFilter === 'BMW' ? null : 'BMW')}/>
                        <label>BMW</label>
                    </div>
                    <div className="input">
                        <input type="checkbox" checked={brandFilter === 'Citroën'} onChange={() => setBrandFilter(brandFilter === 'Citroën' ? null : 'Citroën')}/>
                        <label>Citroën</label>
                    </div>
                    <div className="input">
                        <input type="checkbox" checked={brandFilter === 'Renault'} onChange={() => setBrandFilter(brandFilter === 'Renault' ? null : 'Renault')}/>
                        <label>Renault</label>
                    </div> 
                </div>
                <div>
                    <h3>--- Modèle ---</h3>  

                    {models.length != 0 && models.map((model, index) => (
                        <div className="input">
                            <input type="checkbox" checked={modelFilter === model[index]} onChange={() => setModelFilter(modelFilter === model[index] ? null : model[index])}  />
                            <label>{model[index]}</label>
                        </div>
                    ))}
                </div>
                <div>
                    <h3>--- Type ---</h3>
                    <div className="input">
                        <input type="checkbox" checked={typeFilter === 'électrique'} onChange={() => setTypeFilter(typeFilter === 'électrique' ? null : 'électrique')}/>
                        <label>Électrique</label>
                    </div>
                    <div className="input">
                        <input type="checkbox" checked={typeFilter === 'hybride'} onChange={() => setTypeFilter(typeFilter === 'hybride' ? null : 'hybride')}/>
                        <label>Hybride</label>
                    </div>
                    <div className="input">
                        <input type="checkbox" checked={typeFilter === 'diesel'} onChange={() => setTypeFilter(typeFilter === 'diesel' ? null : 'diesel')} />
                        <label>Diesel</label>
                    </div> 
                </div>
            </div>

            <div className="tab">
                <div className="titles">
                    <div className="titleCol"> marque </div>
                    <div className="titleCol"> modèle </div>
                    <div className="titleCol"> type</div>
                </div>
                <div className="car">
                    {cars.map((car, index) => (
                        <div key={car.id} className={`${"elements"} ${index % 2 === 0 ? "grayBackground" : ''}`} >
                            <div className="col">{car.brand}</div>
                            <div className="col">{car.model}</div>
                            <div className="col">{car.type} </div>
                        </div>
                    ))}
                </div>
            </div>
        </div>
    )
};
